var tesseract = variables.tesseract;
var lastPeriodGDP = variables.lastPeriodGDP;
var trillionsOfSar = variables.trillionsOfSar;
var thousandsOfSar = variables.thousandsOfSar;
var abbreviate = formatters.abbreviate;
var pctChart = formatters.pctChart;
var decimal = formatters.decimal;
var sarTest = formatters.sarTest;
var pctDecimal = formatters.pctDecimal;

var gdpType = "gpdTypeReal" // gpdTypeReal, gpdTypeNominal
var gdpMeasure = "gdpValue" // gdpValue, gdpGrowth, gdpActivity

var translations = {
  title:{
    gpdTypeReal_gdpValue: {en: "Evolution of Real Gross Domestic Product (GDP)", ar: "تطوّر الناتج المحلي الإجمالي الحقيقي"},
    gpdTypeReal_gdpGrowth: {en: "Growth of Real Gross Domestic Product (GDP)", ar: "نمو الناتج المحلي الإجمالي الحقيقي"},
    gpdTypeReal_gdpActivity: {en: "Real Gross Domestic Product by Economic Activity", ar: "الناتج المحلي الإجمالي الحقيقي حسب النشاط الاقتصادي"},
    gpdTypeNominal_gdpValue: {en: "Evolution of Nominal Gross Domestic Product (GDP)", ar: "تطوّر الناتج المحلي الإجمالي الاسمي"},
    gpdTypeNominal_gdpGrowth: {en: "Growth of Nominal Gross Domestic Product (GDP)", ar: "نمو الناتج المحلي الإجمالي الاسمي"},
    gpdTypeNominal_gdpActivity: {en: "Nominal Gross Domestic Product by Economic Activity", ar: "الناتج المحلي الإجمالي الاسمي حسب النشاط الاقتصادي"},
  },
  indicator: {en: "Indicator", ar: "المؤشر"},
  year: {en: "Year", ar: "السنة"},
  value: {en: "Value", ar: "القيمة"},
  xAxis: {en: "Year", ar: "السنة"},
  real: {en: "Real GDP", ar: "الناتج المحلي الإجمالي الحقيقي"},
  nominal: {en: "Nominal GDP", ar: "الناتج المحلي الإجمالي الاسمي"},
  economicActivity: {en: "Economic Activity", ar: "النشاط الاقتصادي"},
  tooltip: {
    gdpGrowth: {
      en: "Growth Rate",
      ar: "معدل النمو"
    },
    gdpValue: {
      en: trillionsOfSar,
      ar: trillionsOfSar
    }
  }
}

var type = gdpType === "gpdTypeReal" ? "GDP" : "Nominal GDP"
var sector = gdpType === "gpdTypeReal" ? "Economic Activity Section" : "Economic Sectors"
var name = gdpType === "gpdTypeReal" ? ("" + (translations["real"][locale])): ("" + (translations["nominal"][locale]))
var cube =  gdpType === "gpdTypeReal" ? "gastat_gdp_annual" : "gastat_nominal_gdp_by_economic_activity_year"
var factor = gdpMeasure === "gdpGrowth" ? 1 : 1000000000000
var measure = gdpMeasure === "gdpGrowth" ? "GDP Growth" : "GDP"
var tooltipFormatter = gdpMeasure === "gdpGrowth" ? pctDecimal : decimal
var tooltipYaxis = gdpMeasure === "gdpGrowth" ? pctChart : abbreviate
var specialCut = gdpType === "gpdTypeReal" ? "Economic+Activity+Section=12&" : ""
var specialExclude = gdpType === "gpdTypeReal" ? "exclude=Economic+Activity+Section:12&" : ""

if(gdpMeasure === "gdpValue" || gdpMeasure === "gdpGrowth"){
  return {
    axisPersist: false,
    data: (tesseract + "/data.jsonrecords?" + specialCut + "cube=" + cube + "&drilldowns=Year&measures=" + type + "&locale=" + locale),
    dataFormat: function (resp) {
      var data = resp.data.map(function (d) { return Object.assign.apply(Object, [ {} ].concat( d )); }).filter(function (d) { return d["Year"] !== 2026; });

      data.forEach(function (d) {
       d["GDP Type"] = name
       d["GDP"] = d[type] * 1000000;
       d["GDP Type ID"] = type === "GDP" ? 1 : 2
       d["GDP Prev"] = data.find(function (h) { return h["Year"] === d["Year"] - 1; }) ? data.find(function (h) { return h["Year"] === d["Year"] - 1; })["GDP"]*1 : null
       d["GDP Growth"] =  d["GDP Prev"] !== null ? ((d["GDP"] - d["GDP Prev"])/d["GDP Prev"]) * 100 : null
      });
      return data.filter(function (d) { return d[measure] !== null; })
    },
    viewDataFormat: function (resp) {
      var data = resp.data.map(function (d) { return Object.assign.apply(Object, [ {} ].concat( d )); });

      data.forEach(function (d) {
        d["GDP"] = d[type] * 1000000;
        d["GDP Prev"] = data.find(function (h) { return h["Year"] === d["Year"] - 1; }) ? data.find(function (h) { return h["Year"] === d["Year"] - 1; })["GDP"]*1 : null
        d["GDP Growth"] =  d["GDP Prev"] !== null ? ((d["GDP"] - d["GDP Prev"])/d["GDP Prev"]) * 100 : null
      });

      return data.filter(function (d) { return d[measure] !== null && d['Year'] != 2026; }).map(function (d) {
        var obj;

        return (( obj = {}, obj[("" + (translations["indicator"][locale]))] = ("" + (translations["title"][(gdpType + "_" + gdpMeasure)][locale])), obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["value"][locale]))] = d[measure], obj ));
      })
    },
    groupBy: "GDP Type ID",
    legend: false,
    label: function (d) { return ""; },
    lineLabels: true,
    lineMarkers: true,
    shapeConfig: {
      Line: {
        label: function label(d) {
          var dataArray = this._filteredData
            	.filter(function (f) { return f["GDP Type ID"] === d["GDP Type ID"]; });
          var maxX = Math.max.apply(Math, dataArray.map(function (f) { return f["Year"] * 1; }));
          var maxData = dataArray
          	.find(function (f) { return f["Year"] * 1 === maxX; });

          return ("" + (tooltipFormatter(maxData[measure] / factor)));
        },
      }
    },
    title: ("" + (translations["title"][(gdpType + "_" + gdpMeasure)][locale])),
    time: "Year",
    timeline: true,
    timelineConfig: {
      brushing: true,
      playButton: true
    },
    type: "LinePlot",
    tooltip: true,
    tooltipConfig: {
      tbody: [
        [("" + (translations["year"][locale])), function (d) { return d["Year"]; }],
        [("" + (translations["tooltip"][gdpMeasure][locale])), function (d) { return tooltipFormatter(d[measure] / factor); }]
      ]
    },
    x: "Year",
    xConfig: {
      title: ("" + (translations["xAxis"][locale])),
      tickFormat: "",
    },
    y: measure,
    yConfig: {
      title: trillionsOfSar,
      tickFormat: function (d) { return tooltipYaxis(d / factor); },
      titleConfig: {
        html: {
          span: "margin-left: -10px;"
        },
      },
    }
  };
}
else {
  return {
    axisPersist: false,
    data: (tesseract + "/data.jsonrecords?" + specialExclude + "cube=" + cube + "&drilldowns=" + sector + ",Year&measures=" + type + "&locale=" + locale),
    dataFormat: function (resp) {
      var data = resp.data.map(function (d) { return Object.assign.apply(Object, [ {} ].concat( d )); }).filter(function (d) { return d["Year"] !== 2026; });

      data.forEach(function (d) {
        d.GDP = d[type] * 1000000;
      });

      return data;
    },
    viewDataFormat: function (resp) {
      var data = resp.data.map(function (d) { return Object.assign.apply(Object, [ {} ].concat( d )); }).filter(function (d) { return d["Year"] !== 2026; });

      data.forEach(function (d) {
        d.GDP = d[type] * 1000000;
      });

      return data.map(function (d) {
        var obj;

        return (( obj = {}, obj[("" + (translations["indicator"][locale]))] = ("" + (translations["title"][(gdpType + "_" + gdpMeasure)][locale])), obj[("" + (translations["economicActivity"][locale]))] = d[sector], obj[("" + (translations["year"][locale]))] = d.Year, obj[("" + (translations["value"][locale]))] = d.GDP, obj ));
      })
    },
    groupBy: sector,
    legendPosition: "bottom",
    legendTooltip: {
      tbody: false,
    },
    legendConfig:{
      label: false,
    },
    label: function (d) { return d[sector]; },
    shapeConfig: {
      Area: {
        label: false
      }
    },
    title: ("" + (translations["title"][(gdpType + "_" + gdpMeasure)][locale])),
    time: "Year",
    timeline: true,
    timelineConfig: {
      brushing: true,
      playButton: true
    },
    type: "StackedArea",
    tooltip: true,
    tooltipConfig: {
      tbody: [
        [("" + (translations["year"][locale])), function (d) { return d["Year"]; }],
        [trillionsOfSar, function (d) { return decimal(d["GDP"] / factor); }]
      ]
    },
    x: "Year",
    xConfig: {
      title: ("" + (translations["xAxis"][locale])),
      tickFormat: "",
    },
    y: "GDP",
    yConfig: {
      title: trillionsOfSar,
      tickFormat: function (d) { return abbreviate(d / factor); },
      titleConfig: {
        html: {
          span: "margin-left: -10px;"
        },
      },
    }
  }
}

