function customSort(a, b) {
  if (a["Category ID"] === "00") { return 1; }
  if (b["Category ID"] === "00") { return -1; }
  return a["Category"].localeCompare(b["Category"]);
}

function customCity (a, b) {
  if (a["City ID"] === 17) { return 1; }
  if (b["City ID"] === 17) { return -1; }
  return a["City"].localeCompare(b["City"]);
}

