const cube =  gdpType === "gpdTypeReal" ? "gastat_gdp_annual" : "gastat_nominal_gdp_by_economic_activity_year"
const factor = gdpMeasure === "gdpGrowth" ? 1 : 1000000000000
const measure = gdpMeasure === "gdpGrowth" ? "GDP Growth" : "GDP"
const tooltipFormatter = gdpMeasure === "gdpGrowth" ? pctDecimal : decimal
const tooltipYaxis = gdpMeasure === "gdpGrowth" ? pctChart : abbreviate
const specialCut = gdpType === "gpdTypeReal" ? "Economic+Activity+Section=12&" : ""
const specialExclude = gdpType === "gpdTypeReal" ? "exclude=Economic+Activity+Section:12&" : ""

if(gdpMeasure === "gdpValue" || gdpMeasure === "gdpGrowth"){
  return {
    axisPersist: false,
    data: `${tesseract}/data.jsonrecords?${specialCut}cube=${cube}&drilldowns=Year&measures=${type}&locale=${locale}`,
    dataFormat: resp => {
      const data = resp.data.map(d => Object.assign({}, ...d)).filter(d => d["Year"] !== 2026);

      data.forEach(d => {
       d["GDP Type"] = name
       d["GDP"] = d[type] * 1000000;
       d["GDP Type ID"] = type === "GDP" ? 1 : 2
       d["GDP Prev"] = data.find(h => h["Year"] === d["Year"] - 1) ? data.find(h => h["Year"] === d["Year"] - 1)["GDP"]*1 : null
       d[`GDP Growth`] =  d["GDP Prev"] !== null ? ((d["GDP"] - d["GDP Prev"])/d["GDP Prev"]) * 100 : null
      });
      return data.filter(d => d[measure] !== null)
    },
    viewDataFormat: (resp) => {
      const data = resp.data.map(d => Object.assign({}, ...d));

      data.forEach(d => {
        d["GDP"] = d[type] * 1000000;
        d["GDP Prev"] = data.find(h => h["Year"] === d["Year"] - 1) ? data.find(h => h["Year"] === d["Year"] - 1)["GDP"]*1 : null
        d[`GDP Growth`] =  d["GDP Prev"] !== null ? ((d["GDP"] - d["GDP Prev"])/d["GDP Prev"]) * 100 : null
      });

      return data.filter(d => d[measure] !== null && d['Year'] != 2026).map(d => ({
        [`${translations["indicator"][locale]}`]: `${translations["title"][`${gdpType}_${gdpMeasure}`][locale]}`,
        [`${translations["year"][locale]}`]: d.Year,
        [`${translations["value"][locale]}`]: d[measure],
      }))
