        label(d) {
          const dataArray = this._filteredData
            	.filter(f => f["GDP Type ID"] === d["GDP Type ID"]);
          const maxX = Math.max(...dataArray.map(f => f["Year"] * 1));
          const maxData = dataArray
          	.find(f => f["Year"] * 1 === maxX);

          return `${tooltipFormatter(maxData[measure] / factor)}`;
        },
      }
    },
    title: `${translations["title"][`${gdpType}_${gdpMeasure}`][locale]}`,
    time: "Year",
    timeline: true,
    timelineConfig: {
      brushing: true,
      playButton: true
    },
    type: "LinePlot",
    tooltip: true,
    tooltipConfig: {
      tbody: [
        [`${translations["year"][locale]}`, d => d["Year"]],
        [`${translations["tooltip"][gdpMeasure][locale]}`, d => tooltipFormatter(d[measure] / factor)]
      ]
