      title: `${translations["xAxis"][locale]}`,
      tickFormat: "",
    },
    y: measure,
    yConfig: {
      title: trillionsOfSar,
      tickFormat: d => tooltipYaxis(d / factor),
      titleConfig: {
        html: {
          span: "margin-left: -10px;"
        },
      },
    }
  };
}
else {
