}

const factor = 1

const dataURL = `${tesseract}/data.jsonrecords?cube=internationally_reported_indicators&drilldowns=Internationally+Reported+Indicators,Year&include=Internationally+Reported+Indicators:47&measures=Value&locale=${locale}`

return {
  cache: false,
  data: dataURL,
  dataFormat: (resp) => {
    const data = resp.data;
    const dataLength = data.length
    if(dataLength <= 6){
      return{
        data: data,
        timeline: false
      }
    }
    else{
      return {
        data: data,
        time: "Year",
        timeline: true,
        timelineConfig: {
          brushing: true,
          playButton: false
        },
      }
    }
  },
  sourceFormat: () => {
    const data = sourceData.filter(d => d["Indicator Name ID"] === 47);
    const sourceInfo = {
      source_name: data[0]["Indicator Source"],
      source_link: data[0]["Indicator Source Link"]
    };
  return sourceInfo;
  }, 
  viewDataFormat: (resp) => {
    return resp.data.map(d => ({
      [`${translations["indicator"][locale]}`]: `${translations["title"][locale]}`,
      [`${translations["year"][locale]}`]: d.Year,
      [`${translations["value"][locale]}`]: d.Value,
    }))
  },
  groupBy: ["Internationally Reported Indicators ID"],
  label: "",
  legend: false,
  lineLabels: true,
  lineMarkers: true,
  lineMarkerConfig: {
    fill: d => {
    	return d.data["Internationally Reported Indicators ID"]*1 === 47 ? "#FDE725" : "gray"
    }
  },
  shapeConfig: {
    fill: "#FDE725",
    Line: {
      stroke: "#FDE725",
      label(d) {
        const dataArray = this._filteredData
          	.filter(f => f["Internationally Reported Indicators ID"] === d["Internationally Reported Indicators ID"]);
        const maxX = Math.max(...dataArray.map(f => f["Year"] * 1));
        const maxData = dataArray
        	.find(f => f["Year"] * 1 === maxX);
        
        return `${pctDecimal(maxData["Value"]*factor)}`;
      },
    }
  },
  title: `${translations["title"][locale]}`,
  tooltipConfig: {
    tbody: d => { 
    let customTooltip = [];
      customTooltip = [
        [`${translations["year"][locale]}`, d["Year"]],
        [`${translations["yAxis"][locale]}`, d["Value"] === 100 ? pctDecimal(d["Value"]*factor) : locale === "en" ? `${(d["Value"].toFixed(2)*factor)}%` : `%${(d["Value"].toFixed(2)*factor)}`]
      ]
      return customTooltip;
    },
  },
  type: "BarChart",
  x: "Year",
  xConfig: {
    rounding: "none",
    title: `${translations["xAxis"][locale]}`,
  },
  y: "Value",
  yConfig: {
    tickFormat: d => pctChart(d*factor),
    title: `${translations["yAxis"][locale]}`
  },
}

